import React, { useState } from "react";
import { buildRouteHref, handleSpaNavClick } from "../../utils/spaNavigation";
import AvatarCropModal from "../AvatarCropModal";
import { NPC_PLAYBOOK_OPTIONS } from "../session/sessionShellUi";

/**
 * Inline faction create/edit form for Campaign Management.
 * When editing: rendered inside CampaignFactionPanel body (replaces NPC grid).
 * When creating (no id): rendered at the list bottom.
 */
const CampaignFactionEditor = ({
  factionForm,
  setFactionForm,
  factionError,
  factionImagePreview,
  factionPreviewError,
  setFactionPreviewError,
  factionCropOpen,
  setFactionCropOpen,
  campaignNPCs,
  factionAddNpcId,
  setFactionAddNpcId,
  onSave,
  onCancel,
  onAddNpc,
  onRemoveNpc,
  onToggleNpcVisibleToPlayers,
  onBulkSetNpcVisibleToPlayers,
  onCreateNpc,
  onNavigateToNPC,
  embedded = false,
  S,
}) => {
  const [createOpen, setCreateOpen] = useState(false);
  const [createName, setCreateName] = useState("");
  const [createPlaybook, setCreatePlaybook] = useState("STAND");
  const [createBusy, setCreateBusy] = useState(false);

  if (!factionForm) return null;

  const resetCreate = () => {
    setCreateOpen(false);
    setCreateName("");
    setCreatePlaybook("STAND");
    setCreateBusy(false);
  };

  const editorId = factionForm.id
    ? `faction-editor-${factionForm.id}`
    : "faction-editor-new";

  return (
    <div
      id={embedded ? undefined : editorId}
      className="campaign-faction-editor"
      style={{
        border: "1px solid var(--hftf-purple)",
        borderLeft: "4px solid var(--hftf-purple)",
        borderRadius: "4px",
        padding: "12px",
        marginTop: embedded ? 0 : "8px",
        background: "var(--hftf-deep)",
      }}
    >
      <span style={S.lbl}>
        {factionForm.id ? "EDIT FACTION" : "CREATE FACTION"}
      </span>
      {factionError && (
        <div style={{ ...S.err, marginBottom: "8px" }}>{factionError}</div>
      )}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "12px",
          alignItems: "flex-start",
          marginBottom: "10px",
        }}
      >
        <div style={{ flexShrink: 0 }}>
          <span
            style={{
              fontSize: "11px",
              color: "var(--text-muted)",
              display: "block",
              marginBottom: "4px",
            }}
          >
            Preview
          </span>
          {factionImagePreview && !factionPreviewError ? (
            <img
              src={factionImagePreview}
              alt=""
              crossOrigin="anonymous"
              onError={() => setFactionPreviewError(true)}
              onLoad={() => setFactionPreviewError(false)}
              style={{
                width: 96,
                height: 96,
                objectFit: "cover",
                borderRadius: 6,
                border: "1px solid var(--border)",
                background: "var(--hftf-deep)",
              }}
            />
          ) : (
            <div
              style={{
                width: 96,
                height: 96,
                borderRadius: 6,
                border: "1px solid var(--border)",
                background: "var(--hftf-deep)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: "var(--text-dim)",
                fontSize: 28,
                fontWeight: "bold",
              }}
              aria-hidden="true"
            >
              {(factionForm.name || "F").trim().charAt(0).toUpperCase()}
            </div>
          )}
        </div>
        <div style={{ flex: "1 1 200px", minWidth: 0 }}>
          <span
            style={{
              fontSize: "11px",
              color: "var(--text-muted)",
              display: "block",
              marginBottom: "4px",
            }}
          >
            Faction image
          </span>
          <input
            type="file"
            accept="image/jpeg,image/png,image/webp,image/gif"
            style={{
              fontSize: "11px",
              color: "var(--hftf-text-cream)",
              maxWidth: "100%",
            }}
            onChange={(e) => {
              const file = e.target.files?.[0];
              e.target.value = "";
              if (!file) return;
              setFactionForm((p) => ({
                ...p,
                imageFile: file,
              }));
              setFactionPreviewError(false);
            }}
          />
          <div style={{ ...S.row, marginTop: 6, gap: 6 }}>
            <button
              type="button"
              disabled={!factionImagePreview || factionPreviewError}
              onClick={() => setFactionCropOpen(true)}
              style={{
                ...S.btnGhost,
                fontSize: "10px",
                opacity:
                  !factionImagePreview || factionPreviewError ? 0.5 : 1,
              }}
            >
              Crop
            </button>
            {(factionForm.image || factionForm.imageFile) && (
              <button
                type="button"
                onClick={() =>
                  setFactionForm((p) => ({
                    ...p,
                    image: null,
                    imageFile: null,
                  }))
                }
                style={{
                  ...S.btnGhost,
                  fontSize: "10px",
                }}
              >
                Clear image
              </button>
            )}
          </div>
          {factionCropOpen &&
          factionImagePreview &&
          !factionPreviewError ? (
            <AvatarCropModal
              imageSrc={factionImagePreview}
              onCancel={() => setFactionCropOpen(false)}
              onApply={(file) => {
                setFactionForm((p) => ({
                  ...p,
                  imageFile: file,
                }));
                setFactionCropOpen(false);
                setFactionPreviewError(false);
              }}
            />
          ) : null}
        </div>
      </div>
      <div className="campaign-faction-editor-fields">
        <div>
          <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
            Name
          </span>
          <input
            style={S.inp}
            value={factionForm.name}
            onChange={(e) =>
              setFactionForm((p) => ({ ...p, name: e.target.value }))
            }
          />
        </div>
        <div>
          <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
            Type
          </span>
          <input
            style={S.inp}
            value={factionForm.faction_type}
            onChange={(e) =>
              setFactionForm((p) => ({
                ...p,
                faction_type: e.target.value,
              }))
            }
            placeholder="e.g. Criminal Syndicate"
          />
        </div>
        <div>
          <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
            Tier
          </span>
          <input
            style={{ ...S.inp, width: "80px" }}
            type="number"
            value={factionForm.level}
            onChange={(e) =>
              setFactionForm((p) => ({
                ...p,
                level: parseInt(e.target.value, 10) || 0,
              }))
            }
          />
        </div>
        <div>
          <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
            Hold
          </span>
          <select
            style={S.select}
            value={factionForm.hold}
            onChange={(e) =>
              setFactionForm((p) => ({ ...p, hold: e.target.value }))
            }
          >
            <option value="weak">Weak</option>
            <option value="strong">Strong</option>
          </select>
        </div>
        <div>
          <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
            Reputation
          </span>
          <input
            style={{ ...S.inp, width: "80px" }}
            type="number"
            value={factionForm.reputation}
            onChange={(e) =>
              setFactionForm((p) => ({
                ...p,
                reputation: parseInt(e.target.value, 10) || 0,
              }))
            }
          />
        </div>
      </div>
      <div style={{ marginBottom: "8px" }}>
        <span style={{ fontSize: "11px", color: "var(--text-muted)" }}>
          Notes
        </span>
        <textarea
          style={{
            ...S.inp,
            height: "50px",
            resize: "vertical",
            border: "1px solid var(--border)",
            background: "var(--hftf-deep)",
            padding: "6px",
          }}
          value={factionForm.notes}
          onChange={(e) =>
            setFactionForm((p) => ({ ...p, notes: e.target.value }))
          }
        />
      </div>
      <div
        style={{
          marginBottom: "12px",
          padding: "8px",
          background: "var(--hftf-deep)",
          borderRadius: "4px",
          border: "1px solid var(--border)",
        }}
      >
        <label
          style={{
            display: "flex",
            alignItems: "center",
            gap: "6px",
            fontSize: "12px",
            marginBottom: "8px",
          }}
        >
          <input
            type="checkbox"
            checked={factionForm.visible_to_players !== false}
            onChange={(e) =>
              setFactionForm((p) => ({
                ...p,
                visible_to_players: e.target.checked,
              }))
            }
          />
          Visible to players (crew standing)
        </label>
        <span
          style={{
            fontSize: "11px",
            color: "var(--text-muted)",
            display: "block",
            marginBottom: "6px",
          }}
        >
          Players may also see:
        </span>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px 14px",
            fontSize: "12px",
          }}
        >
          {[
            ["players_see_tier", "Tier"],
            ["players_see_hold", "Hold"],
            ["players_see_reputation", "Reputation"],
            ["players_see_notes", "Notes"],
            ["players_see_npcs", "NPCs"],
          ].map(([key, label]) => (
            <label
              key={key}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "5px",
                opacity: factionForm.visible_to_players === false ? 0.5 : 1,
              }}
            >
              <input
                type="checkbox"
                disabled={factionForm.visible_to_players === false}
                checked={factionForm[key] !== false}
                onChange={(e) =>
                  setFactionForm((p) => ({
                    ...p,
                    [key]: e.target.checked,
                  }))
                }
              />
              {label}
            </label>
          ))}
        </div>
      </div>
      {factionForm.id && (
        <div
          style={{
            marginBottom: "12px",
            padding: "8px",
            background: "var(--hftf-deep)",
            borderRadius: "4px",
            border: "1px solid var(--border)",
          }}
        >
          <span
            style={{
              fontSize: "11px",
              color: "var(--text-muted)",
              display: "block",
              marginBottom: "6px",
            }}
          >
            NPCs in this faction
          </span>
          {(typeof onBulkSetNpcVisibleToPlayers === "function" ||
            typeof onToggleNpcVisibleToPlayers === "function") &&
          (factionForm.npcs || []).length > 0 ? (
            <div
              style={{
                display: "flex",
                gap: 6,
                flexWrap: "wrap",
                marginBottom: 8,
              }}
            >
              <button
                type="button"
                onClick={() => {
                  if (typeof onBulkSetNpcVisibleToPlayers === "function") {
                    onBulkSetNpcVisibleToPlayers(true);
                    return;
                  }
                  for (const n of factionForm.npcs || []) {
                    if (n?.id != null && n.visible_to_players === false) {
                      onToggleNpcVisibleToPlayers(n.id, true);
                    }
                  }
                }}
                style={{
                  ...S.btn,
                  fontSize: "10px",
                  padding: "2px 6px",
                }}
                title="Players can see all NPCs in this faction"
              >
                Show all members
              </button>
              <button
                type="button"
                onClick={() => {
                  if (typeof onBulkSetNpcVisibleToPlayers === "function") {
                    onBulkSetNpcVisibleToPlayers(false);
                    return;
                  }
                  for (const n of factionForm.npcs || []) {
                    if (n?.id != null && n.visible_to_players !== false) {
                      onToggleNpcVisibleToPlayers(n.id, false);
                    }
                  }
                }}
                style={{
                  ...S.btn,
                  fontSize: "10px",
                  padding: "2px 6px",
                }}
                title="Hide all NPCs in this faction from players"
              >
                Hide all members
              </button>
            </div>
          ) : null}
          {(factionForm.npcs || []).map((n) => (
            <div key={n.id} className="campaign-faction-npc-row">
              {typeof onNavigateToNPC === "function" && n?.id != null ? (
                <a
                  href={buildRouteHref("npcs", { npcId: n.id })}
                  onClick={(e) =>
                    handleSpaNavClick(e, () => onNavigateToNPC(n.id))
                  }
                  style={{
                    minWidth: 0,
                    flex: 1,
                    color: "var(--hftf-text-cream, #e5e7eb)",
                    textDecoration: "underline",
                    textUnderlineOffset: 2,
                    cursor: "pointer",
                  }}
                  title="Open NPC sheet"
                >
                  {n.name || n.stand_name || `NPC ${n.id}`}
                </a>
              ) : (
                <span style={{ minWidth: 0, flex: 1 }}>
                  {n.name || n.stand_name || `NPC ${n.id}`}
                </span>
              )}
              {typeof onToggleNpcVisibleToPlayers === "function" ? (
                <label
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 4,
                    fontSize: 10,
                    whiteSpace: "nowrap",
                    opacity: n.visible_to_players === false ? 0.65 : 1,
                  }}
                  title={
                    factionForm.visible_to_players === false
                      ? "Players will see this NPC once the faction is revealed (and NPCs are shown)"
                      : factionForm.players_see_npcs === false
                        ? "Enable “NPCs” under Players may also see to show members"
                        : "Players see this NPC"
                  }
                >
                  <input
                    type="checkbox"
                    checked={n.visible_to_players !== false}
                    onChange={(e) =>
                      onToggleNpcVisibleToPlayers(n.id, e.target.checked)
                    }
                  />
                  Players see
                </label>
              ) : null}
              <button
                onClick={() => onRemoveNpc(n.id)}
                style={{
                  ...S.btn,
                  fontSize: "10px",
                  padding: "2px 6px",
                  background: "#7f1d1d",
                  color: "#fca5a5",
                }}
              >
                Remove
              </button>
            </div>
          ))}
          {createOpen && typeof onCreateNpc === "function" ? (
            <div
              style={{
                marginTop: "8px",
                padding: "8px",
                border: "1px dashed var(--border)",
                borderRadius: "4px",
                display: "flex",
                flexDirection: "column",
                gap: 8,
              }}
            >
              <span
                style={{
                  fontSize: "11px",
                  color: "var(--text-muted)",
                }}
              >
                Create new NPC
              </span>
              <div>
                <span
                  style={{
                    fontSize: "11px",
                    color: "var(--text-muted)",
                    display: "block",
                    marginBottom: 2,
                  }}
                >
                  Name
                </span>
                <input
                  style={{ ...S.inp, width: "100%", boxSizing: "border-box" }}
                  value={createName}
                  onChange={(e) => setCreateName(e.target.value)}
                  placeholder="e.g. Highway Star"
                  disabled={createBusy}
                  autoFocus
                />
              </div>
              <div>
                <span
                  style={{
                    fontSize: "11px",
                    color: "var(--text-muted)",
                    display: "block",
                    marginBottom: 2,
                  }}
                >
                  Playbook
                </span>
                <select
                  style={{ ...S.select, width: "100%" }}
                  value={createPlaybook}
                  onChange={(e) => setCreatePlaybook(e.target.value)}
                  disabled={createBusy}
                >
                  {NPC_PLAYBOOK_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  type="button"
                  style={S.btnPrimary}
                  disabled={createBusy || !createName.trim()}
                  onClick={async () => {
                    setCreateBusy(true);
                    try {
                      const created = await onCreateNpc({
                        name: createName.trim(),
                        playbook: createPlaybook,
                      });
                      if (created != null) resetCreate();
                    } finally {
                      setCreateBusy(false);
                    }
                  }}
                >
                  {createBusy ? "Creating…" : "Create"}
                </button>
                <button
                  type="button"
                  style={S.btnGhost}
                  disabled={createBusy}
                  onClick={resetCreate}
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <div
              style={{
                display: "flex",
                gap: "8px",
                marginTop: "8px",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <select
                style={{ ...S.select, flex: 1, minWidth: 120 }}
                value={factionAddNpcId}
                onChange={(e) => setFactionAddNpcId(e.target.value)}
              >
                <option value="">Add an NPC...</option>
                {campaignNPCs
                  .filter(
                    (n) =>
                      !(factionForm.npcs || []).some((fn) => fn.id === n.id),
                  )
                  .map((n) => (
                    <option key={n.id} value={n.id}>
                      {n.name || n.stand_name || `NPC ${n.id}`}
                    </option>
                  ))}
              </select>
              <button
                type="button"
                onClick={onAddNpc}
                style={S.btnPrimary}
                disabled={!factionAddNpcId}
              >
                Add
              </button>
              {typeof onCreateNpc === "function" ? (
                <button
                  type="button"
                  onClick={() => setCreateOpen(true)}
                  style={S.btnGhost}
                  title="Create a new NPC in this faction"
                >
                  Create new
                </button>
              ) : null}
            </div>
          )}
        </div>
      )}
      <div style={S.row}>
        <button onClick={onSave} style={S.btnPrimary}>
          Save
        </button>
        <button onClick={onCancel} style={S.btnGhost}>
          Cancel
        </button>
      </div>
    </div>
  );
};

export default CampaignFactionEditor;
