/** ProgressClock model validators: max_segments 1–12. */

export const CLOCK_SEGMENTS_MIN = 1;
export const CLOCK_SEGMENTS_MAX = 12;
export const CLOCK_SEGMENTS_FALLBACK = 4;

/** Postgres integer PK ceiling; Date.now() temp ids are larger and must not be sent. */
export const PERSISTED_CLOCK_ID_MAX = 2147483647;

export function clampClockSegments(raw, fallback = CLOCK_SEGMENTS_FALLBACK) {
  const n = Math.round(Number(raw));
  if (!Number.isFinite(n)) {
    const fb = Math.round(Number(fallback));
    const base = Number.isFinite(fb) ? fb : CLOCK_SEGMENTS_FALLBACK;
    return Math.max(CLOCK_SEGMENTS_MIN, Math.min(CLOCK_SEGMENTS_MAX, base));
  }
  return Math.max(CLOCK_SEGMENTS_MIN, Math.min(CLOCK_SEGMENTS_MAX, n));
}

export function clampClockFilled(filled, segments) {
  const max = clampClockSegments(segments);
  const n = Math.round(Number(filled));
  if (!Number.isFinite(n) || n < 0) return 0;
  return Math.min(max, n);
}

/** Wedge count for the ring — never snap 7 onto 8/12 BitD presets. */
export function clockWedgeCount(segments) {
  return clampClockSegments(segments);
}

/** Filled wedges: early = red → orange → yellow → late = green. */
export const CLOCK_WEDGE_FILL_STOPS = [
  "#dc2626",
  "#ea580c",
  "#ca8a04",
  "#16a34a",
];

export function clockWedgeFillColor(wedgeIndex, totalSegments) {
  const n = Math.max(1, totalSegments);
  const band = Math.min(
    CLOCK_WEDGE_FILL_STOPS.length - 1,
    Math.floor((wedgeIndex / n) * CLOCK_WEDGE_FILL_STOPS.length),
  );
  return CLOCK_WEDGE_FILL_STOPS[band];
}

export function isPersistedProgressClockId(id) {
  if (typeof id === "string" && id.trim() !== "" && !/^\d+$/.test(id.trim())) {
    return false;
  }
  const n = Number(id);
  return Number.isInteger(n) && n > 0 && n <= PERSISTED_CLOCK_ID_MAX;
}

export function normalizeSheetProgressClock(c) {
  if (!c || typeof c !== "object") return null;
  const segments = clampClockSegments(c.segments ?? c.max_segments);
  return {
    ...c,
    id: c.id,
    name: c.name ?? "",
    segments,
    max_segments: segments,
    filled: clampClockFilled(c.filled ?? c.filled_segments, segments),
    filled_segments: clampClockFilled(c.filled ?? c.filled_segments, segments),
    visible_to_party: Boolean(c.visible_to_party),
    visible_to_players: Boolean(c.visible_to_players),
    clock_type: c.clock_type,
    session: c.session,
    description: c.description ?? "",
    completed: Boolean(c.completed),
    created_by: c.created_by,
  };
}

/** Stable React list key — survives temp id → server id remaps after create. */
export function progressClockClientKey(c) {
  if (c?.clientKey != null && String(c.clientKey).trim() !== "") {
    return String(c.clientKey);
  }
  if (c?.id != null && String(c.id).trim() !== "") {
    return `id:${c.id}`;
  }
  return `tmp:${Date.now()}`;
}

/**
 * Merge server clocks onto local list without remounting tiles.
 * Temp clocks match incoming by name + segments; keep prev.clientKey.
 */
export function mergeSheetProgressClocks(prev, incoming) {
  const prevList = Array.isArray(prev) ? prev : [];
  const incList = (Array.isArray(incoming) ? incoming : [])
    .map((c) => normalizeSheetProgressClock(c))
    .filter(Boolean);

  if (!prevList.length) {
    return incList.map((c) => ({
      ...c,
      clientKey: progressClockClientKey(c),
    }));
  }

  const usedInc = new Set();
  const result = [];

  for (const p of prevList) {
    const pn = normalizeSheetProgressClock(p);
    if (!pn) continue;
    let match = null;
    if (isPersistedProgressClockId(pn.id)) {
      match = incList.find(
        (i) => !usedInc.has(i.id) && Number(i.id) === Number(pn.id),
      );
    }
    if (!match && !isPersistedProgressClockId(pn.id)) {
      const name = String(pn.name || "").trim();
      const segs = clockWedgeCount(pn.segments);
      match = incList.find((i) => {
        if (usedInc.has(i.id)) return false;
        return (
          String(i.name || "").trim() === name &&
          clockWedgeCount(i.segments) === segs
        );
      });
    }
    if (match) {
      usedInc.add(match.id);
      result.push({
        ...match,
        clientKey: p.clientKey || progressClockClientKey(p),
      });
      continue;
    }
    if (!isPersistedProgressClockId(pn.id)) {
      result.push({
        ...pn,
        clientKey: p.clientKey || progressClockClientKey(p),
      });
    }
  }

  for (const i of incList) {
    if (usedInc.has(i.id)) continue;
    result.push({
      ...i,
      clientKey: progressClockClientKey(i),
    });
  }

  return result;
}

export function serializeSheetProgressClocks(clocks) {
  if (!Array.isArray(clocks)) return [];
  return clocks
    .map((c) => {
      const n = normalizeSheetProgressClock(c);
      if (!n) return null;
      const row = {
        name: n.name || "Clock",
        clock_type: n.clock_type || "COUNTDOWN",
        max_segments: n.segments,
        segments: n.segments,
        filled_segments: n.filled,
        filled: n.filled,
        visible_to_party: n.visible_to_party,
        visible_to_players: n.visible_to_players,
        description: n.description || "",
        session: n.session ?? null,
      };
      if (isPersistedProgressClockId(n.id)) {
        row.id = Number(n.id);
      }
      return row;
    })
    .filter(Boolean);
}
